#!/usr/bin/env node
// Generate static-host / edge configs from the single source of truth (web/app/js/policy.mjs)
// and the OpenAI range snapshot (server/openai-ranges.json).
//
//   npm run gen:hosts            # (re)write all generated files
//   node scripts/gen-host-configs.mjs --check   # exit 1 if any generated file is stale
//
// Static hosts cannot import policy.mjs at request time, so these files embed its values.
// tests/policy.test.mjs fails if they drift from policy.mjs.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import {
  securityHeaders, contentSecurityPolicy, OPENAI_UA_PATTERN, OPENAI_DENY_HOSTS, isOpenAIHost,
} from '../web/app/js/policy.mjs';
import {
  loadRanges, parseIPv4, parseIPv6, parseIP, parseCIDR, BLOCK_MESSAGE, MAPPED_PREFIX,
} from '../server/bot-policy.mjs';

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const BANNER = 'GENERATED by scripts/gen-host-configs.mjs from web/app/js/policy.mjs and server/openai-ranges.json — do not edit by hand; run `npm run gen:hosts`.';

const EXEMPT = ['/robots.txt', '/ai.txt'];
const ASSET_CACHE = 'public, max-age=3600, must-revalidate';
const NO_CACHE_PATHS = ['/', '/index.html', '/404.html', '/app/', '/app/index.html', '/sw.js', '/app/sw.js', '/robots.txt', '/ai.txt', '/.well-known/security.txt', '/manifest.webmanifest'];
const ASSET_DIRS = ['/assets/*', '/lib/*', '/app/js/*', '/app/css/*', '/app/assets/*'];

/** Headers for blocked (403) responses: everything from policy except the per-agent X-Robots-Tag. */
function blockedHeaders() {
  const h = { ...securityHeaders() };
  delete h['X-Robots-Tag'];
  return { ...h, 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store', 'X-Robots-Tag': 'noindex, nofollow, noarchive' };
}

// ---------------------------------------------------------------------------
// Netlify / Cloudflare Pages `_headers`
// ---------------------------------------------------------------------------
export function renderHeadersFile() {
  const lines = [`# ${BANNER}`, '# Format: Netlify / Cloudflare Pages _headers.', '', '/*'];
  for (const [k, v] of Object.entries(securityHeaders())) lines.push(`  ${k}: ${v}`);
  lines.push('');
  for (const p of ASSET_DIRS) lines.push(p, `  Cache-Control: ${ASSET_CACHE}`, '');
  for (const p of NO_CACHE_PATHS) lines.push(p, '  Cache-Control: no-cache', '');
  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// netlify.toml (build + edge function; headers live in web/_headers so they are defined once)
// ---------------------------------------------------------------------------
export function renderNetlifyToml() {
  const csp = contentSecurityPolicy();
  return `# ${BANNER}
#
# Security + cache headers are defined once, in web/_headers (Netlify reads it from the publish
# directory). They are not repeated here because Netlify merges matching rules from both sources
# and duplicated values (e.g. "DENY, DENY") are invalid for some headers.
# Content-Security-Policy applied via web/_headers:
#   ${csp}

[build]
  publish = "web"
  command = "echo 'Cerebro OS is buildless; publishing web/'"

[build.environment]
  NODE_VERSION = "22"

# Refuse OpenAI agents (user agent, published IP ranges, ChatGPT Referer/Origin) before the CDN
# serves anything. robots.txt and ai.txt stay readable so crawlers can learn the policy.
[[edge_functions]]
  path = "/*"
  function = "block-openai"
  excludedPath = ${JSON.stringify(EXEMPT)}

[[redirects]]
  from = "/app"
  to = "/app/"
  status = 301
  force = true
`;
}

// ---------------------------------------------------------------------------
// vercel.json
// ---------------------------------------------------------------------------
export function renderVercelJson() {
  const sec = Object.entries(securityHeaders()).map(([key, value]) => ({ key, value }));
  const cfg = {
    $schema: 'https://openapi.vercel.sh/vercel.json',
    framework: null,
    buildCommand: null,
    outputDirectory: 'web',
    cleanUrls: false,
    redirects: [{ source: '/app', destination: '/app/', permanent: true }],
    headers: [
      { source: '/(.*)', headers: [...sec, { key: 'Cache-Control', value: ASSET_CACHE }] },
      { source: '/', headers: [{ key: 'Cache-Control', value: 'no-cache' }] },
      { source: '/(.*)/', headers: [{ key: 'Cache-Control', value: 'no-cache' }] },
      { source: '/(.*)\\.html', headers: [{ key: 'Cache-Control', value: 'no-cache' }] },
      { source: '/(sw\\.js|app/sw\\.js|robots\\.txt|ai\\.txt|manifest\\.webmanifest|\\.well-known/security\\.txt)', headers: [{ key: 'Cache-Control', value: 'no-cache' }] },
    ],
  };
  return JSON.stringify(cfg, null, 2) + '\n';
}

// ---------------------------------------------------------------------------
// Edge runtimes (Netlify Edge Function, Cloudflare Worker, Vercel Middleware)
// The IP parser is the same code as server/bot-policy.mjs, serialised with Function#toString.
// ---------------------------------------------------------------------------
function edgeCore(ranges) {
  const table = {};
  for (const [bot, v] of Object.entries(ranges.bots)) table[bot] = v.prefixes;
  return `// ${BANNER}
// Ranges snapshot: ${ranges.snapshotTakenAt ?? 'unknown'} (${Object.entries(table).map(([b, p]) => `${b}: ${p.length}`).join(', ')})

const OPENAI_UA_PATTERN = ${OPENAI_UA_PATTERN.toString()};
const OPENAI_DENY_HOSTS = ${JSON.stringify(OPENAI_DENY_HOSTS)};
const EXEMPT_PATHS = new Set(${JSON.stringify(EXEMPT)});
const BLOCK_MESSAGE = ${JSON.stringify(BLOCK_MESSAGE)};
const BLOCKED_HEADERS = ${JSON.stringify(blockedHeaders(), null, 2)};
const OPENAI_RANGES = ${JSON.stringify(table)};
const MAPPED_PREFIX = ${'0x' + MAPPED_PREFIX.toString(16)}n;

${isOpenAIHost.toString()}
${parseIPv4.toString()}
${parseIPv6.toString()}
${parseIP.toString()}
${parseCIDR.toString()}

let COMPILED = null;
function matchRange(ip) {
  const a = parseIP(ip || '');
  if (!a) return null;
  if (!COMPILED) {
    COMPILED = [];
    for (const [bot, list] of Object.entries(OPENAI_RANGES)) for (const cidr of list) COMPILED.push({ bot, cidr, ...parseCIDR(cidr) });
  }
  for (const r of COMPILED) if (r.family === a.family && (a.value >> r.shift) << r.shift === r.network) return r;
  return null;
}

function hostOf(value) {
  if (!value || value === 'null') return null;
  try { return new URL(value).hostname; } catch { return null; }
}

/** Returns { reason, bot } when the request must be refused, otherwise null. */
function classify(headers, ip) {
  const m = OPENAI_UA_PATTERN.exec(headers.get('user-agent') || '');
  if (m) return { reason: 'user-agent', bot: m[1] };
  const hit = matchRange(ip);
  if (hit) return { reason: 'ip-range', bot: hit.bot };
  const ref = hostOf(headers.get('referer'));
  if (ref && isOpenAIHost(ref)) return { reason: 'referer', bot: ref };
  const origin = hostOf(headers.get('origin'));
  if (origin && isOpenAIHost(origin)) return { reason: 'origin', bot: origin };
  return null;
}

function blockedResponse(verdict) {
  console.log(JSON.stringify({ time: new Date().toISOString(), level: 'warn', msg: 'openai-blocked', ...verdict }));
  return new Response(BLOCK_MESSAGE, { status: 403, headers: BLOCKED_HEADERS });
}
`;
}

export function renderNetlifyEdge(ranges) {
  return `${edgeCore(ranges)}
// Netlify Edge Function (configured in netlify.toml). Returning undefined continues to the CDN.
export default async (request, context) => {
  const url = new URL(request.url);
  if (EXEMPT_PATHS.has(url.pathname)) return;
  const verdict = classify(request.headers, context.ip);
  if (verdict) return blockedResponse(verdict);
};
`;
}

export function renderCloudflareWorker(ranges) {
  return `${edgeCore(ranges)}
// Cloudflare Worker (route it in front of the origin / Pages project, e.g. "cerebro-os.example/*").
// The IP check uses CF-Connecting-IP against OpenAI's published ranges and does not depend on
// request.cf.verifiedBotCategory (which only covers verified, honest bots).
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (!EXEMPT_PATHS.has(url.pathname)) {
      const verdict = classify(request.headers, request.headers.get('cf-connecting-ip'));
      if (verdict) return blockedResponse(verdict);
    }
    return fetch(request);
  },
};
`;
}

export function renderVercelMiddleware(ranges) {
  return `${edgeCore(ranges)}
// Vercel Routing Middleware example. To enable it, copy this file to the project root as
// middleware.js (Vercel runs root middleware for any framework, including static output).
// Returning undefined lets Vercel continue to the static file.
export const config = { matcher: '/((?!robots\\\\.txt$|ai\\\\.txt$).*)' };

export default function middleware(request) {
  const ip = request.headers.get('x-real-ip') || (request.headers.get('x-forwarded-for') || '').split(',')[0].trim();
  const verdict = classify(request.headers, ip);
  if (verdict) return blockedResponse(verdict);
}
`;
}

// ---------------------------------------------------------------------------
// nginx
// ---------------------------------------------------------------------------
const esc = s => s.replace(/[.]/g, '\\.');

export function renderNginxIpDeny(ranges) {
  const lines = [`# ${BANNER}`, `# OpenAI published crawler ranges, snapshot ${ranges.snapshotTakenAt ?? 'unknown'}. Used by: geo $cerebro_openai_ip { include … }`];
  const seen = new Set(); // bots share some prefixes; nginx warns on duplicate geo networks
  for (const [bot, v] of Object.entries(ranges.bots)) {
    lines.push(`# ${bot} (creationTime ${v.creationTime ?? 'unknown'}, ${v.prefixes.length} prefixes)`);
    for (const p of v.prefixes) {
      if (seen.has(p)) { lines.push(`# ${p} (also listed above)`); continue; }
      seen.add(p);
      lines.push(`${p} 1;`);
    }
  }
  return lines.join('\n') + '\n';
}

export function renderNginxConf() {
  const sec = securityHeaders();
  const hdr = (h, indent) => Object.entries(h).map(([k, v]) => `${indent}add_header ${k} "${v}" always;`).join('\n');
  const blocked = blockedHeaders();
  delete blocked['Content-Type'];
  const hostAlt = OPENAI_DENY_HOSTS.map(esc).join('|');
  const hostRe = `"~*^https?://([^/@]*\\.)?((${hostAlt})(:[0-9]+)?(/|$)|openai\\.)"`;
  return `# ${BANNER}
#
# Install (official nginx image): copy this file to /etc/nginx/conf.d/default.conf (it is
# http-context: maps + one server block), copy deploy/openai-ip-deny.conf to
# /etc/nginx/openai-ip-deny.conf, and copy web/ to /usr/share/nginx/html.
#
# Behind a load balancer, uncomment the realip lines so $remote_addr (used by the geo block)
# is the real client address:
# set_real_ip_from 10.0.0.0/8;
# real_ip_header X-Forwarded-For;
# real_ip_recursive on;

# 1) OpenAI user agents
map $http_user_agent $cerebro_openai_ua {
    default 0;
    "~*${OPENAI_UA_PATTERN.source}" 1;
}

# 2) OpenAI published IP ranges (regenerate with \`npm run refresh:openai\`)
geo $cerebro_openai_ip {
    default 0;
    include /etc/nginx/openai-ip-deny.conf;
}

# 3) Requests initiated from ChatGPT / OpenAI pages (browsing, canvas, embedding)
map $http_referer $cerebro_openai_ref {
    default 0;
    ${hostRe} 1;
}
map $http_origin $cerebro_openai_origin {
    default 0;
    ${hostRe} 1;
}

# robots.txt and ai.txt are served to everyone so crawlers can read the policy.
map $uri $cerebro_policy_exempt {
    default 0;
${EXEMPT.map(p => `    ${p} 1;`).join('\n')}
}

map "$cerebro_policy_exempt$cerebro_openai_ua$cerebro_openai_ip$cerebro_openai_ref$cerebro_openai_origin" $cerebro_openai_block {
    default 1;
    "00000" 0;
    "~^1" 0;
}

map $uri $cerebro_cache_control {
    default "${ASSET_CACHE}";
    "~/$" "no-cache";
    "~*\\.html?$" "no-cache";
    /app "no-cache";
${NO_CACHE_PATHS.filter(p => !p.endsWith('/') && !p.endsWith('.html')).map(p => `    ${p} "no-cache";`).join('\n')}
}

server {
    listen 80;
    listen [::]:80;
    server_name _;
    root /usr/share/nginx/html;
    index index.html;
    charset utf-8;
    server_tokens off;
    absolute_redirect off;

    gzip on;
    gzip_vary on;
    gzip_comp_level 6;
    gzip_min_length 1024;
    gzip_types text/css text/plain text/javascript application/javascript application/json application/manifest+json image/svg+xml;

    # Security headers from policy.mjs (repeated in @openai_blocked because add_header does not inherit
    # into blocks that define their own).
${hdr(sec, '    ')}
    add_header Cache-Control $cerebro_cache_control always;

    # OpenAI agents → 403 (418 is an internal sentinel so genuine 403s keep the default page).
    error_page 418 = @openai_blocked;
    if ($cerebro_openai_block) {
        return 418;
    }

    location @openai_blocked {
        default_type "text/plain; charset=utf-8";
${hdr(blocked, '        ')}
        return 403 ${JSON.stringify(BLOCK_MESSAGE)};
    }

    error_page 404 /404.html;

    # Dotfiles are never served, except /.well-known/.
    location ~ /\\.(?!well-known/) {
        return 404;
    }

    location ~* \\.mjs$ {
        types { }
        default_type "text/javascript; charset=utf-8";
        try_files $uri =404;
    }

    location ~* \\.webmanifest$ {
        types { }
        default_type "application/manifest+json; charset=utf-8";
        try_files $uri =404;
    }

    location = /app {
        return 301 /app/;
    }

    location /app/ {
        try_files $uri $uri/ /app/index.html;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
`;
}

// ---------------------------------------------------------------------------

export function renderAll(ranges = loadRanges()) {
  return {
    'web/_headers': renderHeadersFile(),
    'netlify.toml': renderNetlifyToml(),
    'netlify/edge-functions/block-openai.js': renderNetlifyEdge(ranges),
    'vercel.json': renderVercelJson(),
    'deploy/vercel-middleware.js': renderVercelMiddleware(ranges),
    'deploy/cloudflare-worker.mjs': renderCloudflareWorker(ranges),
    'deploy/nginx.conf': renderNginxConf(),
    'deploy/openai-ip-deny.conf': renderNginxIpDeny(ranges),
  };
}

export function writeAll(files) {
  for (const [rel, content] of Object.entries(files)) {
    const abs = path.join(ROOT, rel);
    mkdirSync(path.dirname(abs), { recursive: true });
    writeFileSync(abs, content);
  }
}

export function staleFiles(files = renderAll()) {
  return Object.entries(files).filter(([rel, content]) => {
    try { return readFileSync(path.join(ROOT, rel), 'utf8') !== content; } catch { return true; }
  }).map(([rel]) => rel);
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  if (process.argv.includes('--check')) {
    const stale = staleFiles();
    if (stale.length) {
      console.error(`Stale generated files (run \`npm run gen:hosts\`):\n  ${stale.join('\n  ')}`);
      process.exit(1);
    }
    console.log('Generated host configs are up to date.');
  } else {
    const files = renderAll();
    writeAll(files);
    for (const rel of Object.keys(files)) console.log(`wrote ${rel}`);
  }
}
